// Reviewing a life never spends the continuation or imports a new campaign.
var rebirthReviewAttempt=null,rebirthReviewTab='성적표',rebirthReviewPage=0;
const lifeReviewRender=renderRebirthDialog;renderRebirthDialog=function(){
 lifeReviewRender();if(!season.rebirth)return;
 if(rebirthPage!=='review'){const b=document.createElement('button');b.type='button';b.dataset.rebirth='review';b.textContent='돌아보기';rebirthDialog.querySelector('nav').append(b);return;}
 const d=RebirthReview.read(season,rebirthReviewAttempt??season.rebirth.attempt);if(!d.valid)return;const esc=escapeText,body=rebirthDialog.querySelector('.rebirth-body'),footer=rebirthDialog.querySelector('footer'),metric=(label,n)=>'<article><small>'+label+'</small><b>'+n+'</b></article>';let content='',pages=1;
 $('rebirth-title').textContent=d.attempt+'번째 삶 돌아보기';rebirthDialog.dataset.review='true';
 rebirthDialog.querySelector('header small').textContent='토투넘 · '+(d.current?'현재':'지난')+' '+d.attempt+'번째 삶 · '+d.memory;
 if(rebirthReviewTab==='성적표')content='<div class="life-review-metrics">'+metric('승리',d.wins)+metric('무승부',d.draws)+metric('패배',d.losses)+metric('승점',d.points)+metric('득점',d.goals)+metric('실점',d.conceded)+'</div><p class="rebirth-note">'+esc(d.owner)+' · 지킨 약속 '+d.fulfilled+' / 놓친 약속 '+d.missed+'</p><p class="rebirth-note">'+esc(d.warning?'최후통첩 실제 승점 '+d.warning.points+' / 3점 · '+d.warning.remaining+'경기 남음':d.status==='returned'?'네 번의 승격을 마치고 1부로 귀환했습니다.':'리그 '+d.played+'경기 · 이사회 여유 '+d.pressure)+'</p>';
 else if(rebirthReviewTab==='약속'){pages=Math.max(1,d.promises.length);rebirthReviewPage=Math.min(rebirthReviewPage,pages-1);const p=d.promises.slice().reverse()[rebirthReviewPage];content=p?'<article class="life-review-promise"><b>'+esc(p.speaker)+' · '+(p.success?'달성':'미달성')+'</b><p>'+esc(p.label)+'</p><small>'+esc(p.target)+' · 실제 '+p.value+' '+esc({points:'점',goals:'득점',conceded:'실점',wins:'승'}[p.metric])+'</small><div>'+p.games.map(g=>'<span>'+g.year+'시즌 '+g.round+'R · '+g.score.join(' : ')+'</span>').join('')+'</div></article>':'<p class="rebirth-note">아직 판정이 끝난 약속이 없습니다. 다음 세 경기의 결과를 미리 정하지 않습니다.</p>';}
 else{pages=Math.max(1,Math.ceil(d.games.length/3));rebirthReviewPage=Math.min(rebirthReviewPage,pages-1);content='<div class="life-review-games">'+d.games.slice().reverse().slice(rebirthReviewPage*3,rebirthReviewPage*3+3).map(g=>'<article><span>'+g.year+'시즌 '+g.round+'R · '+g.division+'부</span><b>'+g.score.join(' : ')+'</b><small>'+ (g.score[0]>g.score[1]?'승리':g.score[0]===g.score[1]?'무승부':'패배')+'</small></article>').join('')+'</div><p class="rebirth-note">확정 리그 결과 · 우리 : 상대 · 컵은 계약 압박에서 제외합니다.</p>';}
 const attempts=[...season.rebirth.previous.map(p=>p.attempt),season.rebirth.attempt];body.innerHTML='<div class="life-review-pickers"><label>삶<select id="life-review-attempt" aria-label="돌아볼 삶">'+attempts.map(a=>'<option value="'+a+'"'+(a===d.attempt?' selected':'')+'>'+a+'번째 삶'+(a===season.rebirth.attempt?' · 현재':' · 이전')+'</option>').join('')+'</select></label><label>기록<select id="life-review-tab" aria-label="삶의 기록 항목">'+['성적표','약속','경기'].map(t=>'<option'+(t===rebirthReviewTab?' selected':'')+'>'+t+'</option>').join('')+'</select></label></div>'+content;
 footer.innerHTML=(pages>1?'<div class="life-review-pager"><button type="button" data-life-review-page="-1"'+(rebirthReviewPage===0?' disabled':'')+'>이전</button><span>'+(rebirthReviewPage+1)+' / '+pages+'</span><button type="button" data-life-review-page="1"'+(rebirthReviewPage===pages-1?' disabled':'')+'>다음</button></div>':'')+'<button type="button" data-rebirth="current">이번 삶의 계약으로</button>';
 $('life-review-attempt').onchange=e=>{rebirthReviewAttempt=Number(e.target.value);rebirthReviewPage=0;renderRebirthDialog();$('life-review-attempt').focus({preventScroll:true});};$('life-review-tab').onchange=e=>{rebirthReviewTab=e.target.value;rebirthReviewPage=0;renderRebirthDialog();$('life-review-tab').focus({preventScroll:true});};
};
rebirthDialog.addEventListener('click',e=>{const action=e.target.closest('[data-rebirth]')?.dataset.rebirth,page=e.target.closest('[data-life-review-page]');if(rebirthBusy)return;if(action==='review'){rebirthReviewAttempt=season.rebirth.attempt;rebirthReviewTab='성적표';rebirthReviewPage=0;rebirthPage='review';renderRebirthDialog();}else if(page){rebirthReviewPage+=Number(page.dataset.lifeReviewPage);renderRebirthDialog();}else if(action)delete rebirthDialog.dataset.review;});
